# One more theory check: what if the beam narrows based on consecutive empty rows above?
# Or what if only holes in rows within 1 stripe of source get filled?

def test_theories():
    input_grid = [
        [0, 0, 0, 0, 0, 0, 2, 0, 0, 0, 0, 0, 0, 0],  # R0
        [0]*14,   # R1
        [8, 8, 8, 8, 0, 8, 8, 8, 8, 8, 8, 8, 8, 8],  # R2
        [0]*14,   # R3
        [8, 8, 0, 8, 8, 8, 8, 0, 8, 8, 8, 0, 8, 8],  # R4
        [0]*14,   # R5
        [0]*14,   # R6
        [8, 8, 0, 8, 8, 8, 8, 8, 8, 0, 8, 8, 8, 8],  # R7
        [0]*14,   # R8
        [0]*14,   # R9
        [8, 8, 8, 8, 0, 8, 8, 0, 8, 8, 8, 0, 8, 8],  # R10
        [0]*14,   # R11
        [0]*14,   # R12
        [0]*14,   # R13
        [0]*14,   # R14
    ]

    theories = {
        "dist<=3": [],
        "stripe 1-2 only": [],
        "dist<=2": []
    }

    for name, threshold in [("dist<=3", 3), ("dist<=2", 2), ("stripe 1-2 only", None)]:
        result = [list(row) for row in input_grid]
        src_col = 6

        for r in range(len(result)):
            if any(v == 8 for v in result[r]):
                for c, v in enumerate(result[r]):
                    if v == 0:
                        dist = abs(c - src_col)
                        if threshold is None:
                            # Only stripes within 2 rows of source
                            if r <= src_col + 2 + 1:  # stripes at R2, R4, R7
                                if dist <= 3:
                                    result[r][c] = 2
                        else:
                            if dist <= threshold:
                                result[r][c] = 2
        theories[name] = [[v for v in row] for row in result]

    print("Comparing theories:")
    for name, t in theories.items():
        print(f"\n{name}:")
        for i, row in enumerate(t):
            zeros = [(j, v) for j, v in enumerate(row) if v == 0 and any(v==8 for v in row)]
            twos = [(j, v) for j, v in enumerate(row) if v == 2]
            if twos:
                print(f"  R{i}: holes={zeros}, filled with 2 at cols={sorted([x[0] for x in twos])}")

test_theories()

