# New approach: Combine both horizontal AND vertical constraints!
# A hole gets filled if:
# 1. The column has a non-zero above it (from source)
# AND
# 2. The row has that column within some horizontal distance of source (dist <= k)

input_grid = [
    [0, 0, 0, 0, 0, 0, 2, 0, 0, 0, 0, 0, 0, 0],  # R0: source at col 6
    [0]*14,   # R1
    [8, 8, 8, 8, 0, 8, 8, 8, 8, 8, 8, 8, 8, 8],  # R2
    [0]*14,   # R3
    [8, 8, 0, 8, 8, 8, 8, 0, 8, 8, 8, 0, 8, 8],  # R4
    [0]*14,   # R5
    [0]*14,   # R6
    [8, 8, 0, 8, 8, 8, 8, 8, 8, 0, 8, 8, 8, 8],  # R7
    [0]*14,   # R8
    [0]*14,   # R9
    [8, 8, 8, 8, 0, 8, 8, 0, 8, 8, 8, 0, 8, 8],  # R10
]

def test_with_both_constraints(horizontal_threshold):
    result = [list(row) for row in input_grid]

    for r in range(len(result)):
        if any(v == 8 for v in result[r]):
            # Find active columns (those with non-zero above)
            active_cols = set()
            for rr in range(0, r+1):
                for c, v in enumerate(result[rr]):
                    if v != 0:
                        active_cols.add(c)

            # Fill holes in ACTIVE columns ONLY if they're horizontally close
            for c, v in enumerate(result[r]):
                if v == 0:
                    dist_from_source = abs(c - 6)
                    if dist_from_source <= horizontal_threshold and c in active_cols:
                        result[r][c] = 2

    return result

print("Testing combined horizontal + vertical constraint:")
for thresh in [2, 3, 4]:
    print(f"\nThreshold={thresh}:")
    result = test_with_both_constraints(thresh)
    for r, row in enumerate(result):
        twos = [(c, v) for c, v in enumerate(result[r]) if v == 2]
        if twos:
            print(f"R{r}: {[(v if v!=0 else '.') for v in row]}")
